const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',file:'<path d="M14 2H5v20h14V7zM14 2v5h5M8 12h8M8 16h6"/>',check:'<path d="m5 12 4 4L19 6"/>',sync:'<path d="M20 7a8 8 0 0 0-14-2L3 8m0-5v5h5M4 17a8 8 0 0 0 14 2l3-3m0 5v-5h-5"/>',alert:'<path d="m12 3 10 18H2zM12 9v5M12 17v1"/>',chart:'<path d="M4 3v18h18M8 16v-5M13 16V7M18 16V4"/>',building:'<path d="M4 21V3h12v18M16 10h4v11M8 7h4M8 11h4M8 15h4M2 21h20"/>',plug:'<path d="M8 3v5M16 3v5M5 8h14v3a7 7 0 0 1-14 0zM12 18v4"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17v.1"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8h18M16 13h5M5 5V3h12"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.file}</svg>`;
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const eur=value=>new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(value);
const companies=[{id:'alba',name:'Alba Retail, S.L.',initials:'AR',sector:'Comercio y distribución',code:'1000'},{id:'norte',name:'Norte Estudio, S.L.',initials:'NE',sector:'Arquitectura y diseño',code:'2000'},{id:'oliva',name:'Oliva Hospitality, S.L.',initials:'OH',sector:'Hostelería y restauración',code:'3000'}];
const statusNames={received:'Recibida',review:'Por validar',validated:'Por aprobar',approved:'Aprobada',exported:'En SAP · demo',reconciled:'Conciliada',issue:'Incidencia'};
const statusClass={received:'neutral',review:'warning',validated:'blue',approved:'',exported:'blue',reconciled:'',issue:'red'};
const names=['Suministros Litoral','Cloud Iberia','Estudio Prisma','Logística Vega','Papelería Central','Energía Horizonte','Mobiliario Roble','Servicios Álamo','Hotel Mirador','Distribuciones Sur','Consultoría Atlas','Talleres Brisa'];
const round=value=>Math.round((value+Number.EPSILON)*100)/100;
const total=invoice=>round(invoice.base*(1+invoice.vat/100));
function seed(){const invoices=Array.from({length:24},(_,index)=>{const state=['review','validated','approved','exported','reconciled','issue','approved','review'][index%8];return{id:`FAC-${2026}-${String(index+81).padStart(4,'0')}`,company:companies[index%3].id,kind:index%4===2?'issued':'received',partner:names[index%12],nif:index%8===5?'':'DEMO-'+String(index+101),date:`2026-10-${String(3+index).padStart(2,'0')}`,due:'2026-11-15',base:[1240,349,2800,680,1450,230,3980,790][index%8],vat:21,status:state,confidence:91+index%9,issue:index%8===5?'Falta el identificador fiscal de demostración.':'',sapRef:['exported','reconciled'].includes(state)?`SIM-5100${index+40}`:'',history:[{time:'28 oct · 09:15',text:'Documento ficticio incorporado a la demo.'}]}});return{version:1,invoices,transactions:invoices.filter(invoice=>['exported','reconciled'].includes(invoice.status)).map((invoice,index)=>({id:`MOV-${index+1}`,company:invoice.company,partner:invoice.partner,amount:total(invoice)*(invoice.kind==='received'?-1:1),date:'2026-10-28',invoiceId:invoice.id,matched:invoice.status==='reconciled'})),events:[{time:'09:15',text:'Entorno de demostración preparado · 3 empresas y 24 facturas ficticias.'}]};}
const key='nexo-demo-v1';let db;try{db=JSON.parse(localStorage.getItem(key));if(db?.version!==1||!Array.isArray(db.invoices))db=seed()}catch{db=seed()}
let page='dashboard',company='all',kind='all',query='',filter='all',selected=null,lastFocus=null;
const pages={dashboard:['Resumen','Tu despacho, bajo control.','Una visión clara de las facturas y del trabajo que necesita tu atención.'],invoices:['Facturas','Cada factura, en su sitio.','Recepción, validación y seguimiento en una única bandeja.'],approvals:['Aprobaciones','El siguiente paso, contigo.','Revisa las facturas validadas y autoriza su exportación simulada.'],reconciliation:['Conciliación','Las cuentas, conectadas.','Relaciona movimientos bancarios ficticios con facturas exportadas.'],issues:['Incidencias','Nada se queda pendiente.','Resuelve las excepciones antes de continuar el circuito.'],metrics:['Métricas','Datos para decidir mejor.','Indicadores calculados a partir de las facturas de esta demostración.'],companies:['Empresas','Una vista. Todas tus empresas.','Tres sociedades ficticias, un mismo espacio de trabajo.'],sap:['Integración SAP','De la aprobación al ERP.','Explora un conector conceptual con trazabilidad de cada paso.']};
const scope=()=>db.invoices.filter(invoice=>company==='all'||invoice.company===company);
const companyName=id=>companies.find(item=>item.id===id)?.name||id;
const badge=invoice=>`<span class="badge ${statusClass[invoice.status]}"><span>●</span>${statusNames[invoice.status]}</span>`;
function save(){try{localStorage.setItem(key,JSON.stringify(db))}catch{toast('Los cambios se conservan solo durante esta sesión: almacenamiento no disponible.')}}
function toast(message){const element=document.getElementById('toast');element.textContent=message;element.className='toast-show';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>element.className='',4500)}
function log(invoice,text){const time=new Date().toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'});invoice.history.unshift({time,text});db.events.unshift({time,text:`${invoice.id} · ${text}`});save()}
function navigate(next){page=next;filter='all';query='';kind='all';render();window.scrollTo(0,0)}
function navItem(id,label,ic,count){return `<button class="nav-item ${page===id?'active':''}" data-page="${id}">${icon(ic)}${label}${count?`<span class="nav-count">${count}</span>`:''}</button>`}
function render(){const invoices=scope();const info=pages[page];document.getElementById('app').innerHTML=`<div class="mobile-scrim" data-action="menu"></div><aside class="sidebar"><div class="brand"><div class="brand-mark">${icon('sync')}</div>nexo<span>DEMO</span></div><div class="workspace"><div class="avatar">AC</div><div><strong>Áurea Consultores</strong><small>Espacio de demostración</small></div></div><div class="nav-label">Espacio de trabajo</div><nav>${navItem('dashboard','Resumen','grid')}${navItem('invoices','Facturas','file',invoices.length)}${navItem('approvals','Aprobaciones','check',invoices.filter(item=>item.status==='validated').length)}${navItem('reconciliation','Conciliación','sync')}${navItem('issues','Incidencias','alert',invoices.filter(item=>item.status==='issue').length)}${navItem('metrics','Métricas','chart')}</nav><div class="nav-label">Administración</div><nav>${navItem('companies','Empresas','building')}${navItem('sap','Integración SAP','plug')}</nav><div class="side-bottom"><div class="demo-box"><strong><span class="dot"></span>Entorno de demostración</strong><br>Datos ficticios · IA y SAP simulados</div><button class="nav-item" data-action="guide">${icon('help')}Guía de la demo</button><div class="profile"><div class="avatar">ML</div><div><strong>María López</strong><small>Gestora · Perfil ficticio</small></div></div></div></aside><main class="main"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir menú">${icon('menu')}</button><div class="breadcrumb">Espacio de trabajo <span>/</span> <strong>${info[0]}</strong></div><div class="top-actions"><select id="company" aria-label="Empresa"><option value="all">Todas las empresas</option>${companies.map(item=>`<option value="${item.id}" ${company===item.id?'selected':''}>${item.name}</option>`).join('')}</select><button class="icon-btn" data-action="guide" aria-label="Guía de demostración">${icon('help')}</button><div class="avatar">ML</div></div></header><div class="content"><div class="page-head"><div><h1>${info[1]}</h1><p>${info[2]}</p></div><div class="actions"><button class="button" data-action="csv">${icon('download')}Exportar CSV</button><button class="button primary" data-action="new">${icon('plus')}Nueva factura</button></div></div>${renderPage()}<footer class="footer"><span>© 2026 Nexo · Demo para despachos contables</span><span>Datos ficticios · Sin conexión real a SAP · Sin certificación de cumplimiento fiscal</span></footer></div></main>`;bind();}
function stats(){const invoices=scope();const pending=invoices.filter(item=>['received','review','validated'].includes(item.status)).length;const synced=invoices.filter(item=>['exported','reconciled'].includes(item.status)).length;return `<div class="stats">${stat('Facturas gestionadas',invoices.length,'file','En el conjunto de datos de la demo')}${stat('Volumen total',eur(invoices.reduce((sum,item)=>sum+total(item),0)),'wallet','Importe bruto · recibidas y emitidas')}${stat('Pendientes de revisión',pending,'clock','Recepción, validación y aprobación')}${stat('Exportadas a SAP',synced,'plug','Exportación simulada',true)}</div>`}
function stat(label,value,ic,foot,positive=false){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(ic)}</span></div><div class="stat-number">${value}</div><div class="stat-foot ${positive?'positive':''}"><span class="dot"></span>${foot}</div></div>`}
function chart(){const invoices=scope();const groups=[0,1,2,3].map(index=>{const rows=invoices.filter(item=>Math.min(3,Math.floor((Number(item.date.slice(-2))-1)/7))===index);return{received:rows.filter(item=>item.kind==='received').length,issued:rows.filter(item=>item.kind==='issued').length}});const max=Math.max(1,...groups.flatMap(group=>[group.received,group.issued]));return `<section class="panel"><div class="panel-head"><div><h2>Actividad de facturación</h2><p>Octubre 2026 · número de facturas por semana</p></div><div class="legend"><span><i></i>Recibidas</span><span><i class="light"></i>Emitidas</span></div></div><div class="chart" role="img" aria-label="Facturas por semana: ${groups.map((group,index)=>`semana ${index+1}, ${group.received} recibidas y ${group.issued} emitidas`).join('; ')}"><div class="axis"><span>${max}</span><span>${Math.round(max/2)}</span><span>0</span></div><div class="bars">${groups.map((group,index)=>`<div class="bar-group"><div class="bar" title="${group.received} recibidas" style="height:${group.received/max*100}%"></div><div class="bar light" title="${group.issued} emitidas" style="height:${group.issued/max*100}%"></div><span class="bar-label">${['01–07 oct','08–14 oct','15–21 oct','22–28 oct'][index]}</span></div>`).join('')}</div></div></section>`}
function renderPage(){const invoices=scope();if(page==='dashboard')return `<div class="hero"><div><div class="eyebrow">MENOS TAREAS. MÁS PERSPECTIVA.</div><h2>De la factura al asiento, sin perder el hilo.</h2><p>Un circuito conectado para tu equipo y cada una de tus empresas.<br>Descubre el flujo completo con una factura de ejemplo.</p></div><div class="hero-visual"><div class="flow-node">${icon('file')}</div><span class="arrow">→</span><div class="flow-node">${icon('spark')}</div><span class="arrow">→</span><div class="flow-node">${icon('check')}</div></div><button class="button soft" data-action="guide">Ver recorrido ${icon('arrow')}</button></div>${stats()}<div class="grid-two">${chart()}<section class="panel"><div class="panel-head"><div><h2>Tu atención, aquí</h2><p>Prioridades de este espacio de trabajo</p></div><span class="badge neutral">En directo</span></div>${task('approvals','check','green','Facturas listas para aprobar',`${invoices.filter(item=>item.status==='validated').length} pendientes de tu revisión`)}${task('issues','alert','','Incidencias por resolver',`${invoices.filter(item=>item.status==='issue').length} documentos requieren cambios`)}${task('sap','plug','blue','Preparadas para SAP',`${invoices.filter(item=>item.status==='approved').length} listas para exportación simulada`)}</section></div>${tablePanel(true)}`;
if(['invoices','approvals','issues'].includes(page))return `${page==='issues'?'<div class="notice amber">Las incidencias bloquean la aprobación y exportación. Abre una factura, corrige sus datos y vuelve a validarla.</div>':''}${tablePanel()}`;
if(page==='companies')return `<div class="company-grid">${companies.map(item=>{const rows=db.invoices.filter(invoice=>invoice.company===item.id);return `<section class="panel company-card"><div class="avatar">${item.initials}</div><h2>${item.name}</h2><p>${item.sector} · Sociedad demo ${item.code}</p><div class="stat-number">${eur(rows.reduce((sum,invoice)=>sum+total(invoice),0))}</div><p>${rows.length} facturas · Identidad ficticia</p><button class="button" data-company="${item.id}">Abrir empresa ${icon('arrow')}</button></section>`}).join('')}</div>`;
if(page==='sap')return `<div class="notice">Conector conceptual SAP · No se realizan llamadas externas ni se crean asientos reales. El formato CSV es ilustrativo y requiere adaptar el mapeo a la versión de SAP del cliente.</div><div class="integration-grid"><section class="panel integration"><span class="sap">SAP</span><h2>Conector de contabilización</h2><p>Destino ilustrativo: SAP S/4HANA / ECC<br>Sociedad → Proveedor/cliente → Base → IVA → Total<br>Estado: simulador local · Sin credenciales</p><span class="badge blue">Simulación activa</span><div class="modal-actions"><button class="button primary" data-action="export-all">${icon('plug')}Exportar ${invoices.filter(item=>item.status==='approved').length} aprobadas</button></div></section><section class="panel integration"><h2>Prueba una excepción de integración</h2><p>Simula una indisponibilidad del conector en la próxima exportación. La factura conservará su aprobación y podrás reintentar sin duplicar registros.</p><label class="check-line"><input id="sap-fail" type="checkbox" ${db.failNext?'checked':''}>Simular fallo en la próxima exportación</label><p>Las referencias SIM identifican respuestas ficticias. Solo se exportan facturas aprobadas.</p><button class="button" data-action="csv">${icon('download')}Descargar datos ilustrativos</button></section></div><section class="panel"><div class="panel-head"><h2>Registro de actividad de la demo</h2><span class="badge neutral">Local</span></div><div class="log-list">${db.events.slice(0,15).map(event=>`<div class="log-line"><time>${escapeHtml(event.time)}</time><strong>${escapeHtml(event.text)}</strong></div>`).join('')}</div></section>`;
if(page==='reconciliation')return reconciliation();
if(page==='metrics'){const done=invoices.filter(item=>item.status==='reconciled').length;return `${stats()}<div class="grid-two">${chart()}<section class="panel"><div class="panel-head"><div><h2>Estado del circuito</h2><p>Distribución real del conjunto ficticio seleccionado</p></div></div><div class="metric-list">${Object.entries(statusNames).map(([state,label])=>{const count=invoices.filter(item=>item.status===state).length;return `<div class="metric-row"><span>${label}</span><strong>${count}</strong></div>`}).join('')}<div class="progress-track"><div class="progress-fill" style="width:${invoices.length?done/invoices.length*100:0}%"></div></div><p class="small muted" style="margin-top:12px">${invoices.length?Math.round(done/invoices.length*100):0}% del circuito completado</p></div></section></div><div class="notice">Estas métricas describen los datos ficticios actuales. No representan ahorro de tiempo, precisión de OCR ni resultados reales de un despacho.</div>`}return '';}
function task(target,ic,color,title,subtitle){return `<button class="task" data-page="${target}"><span class="task-icon ${color}">${icon(ic)}</span><span><strong>${title}</strong><small>${subtitle}</small></span><span>${icon('arrow')}</span></button>`}
function filtered(){return scope().filter(invoice=>(page!=='approvals'||invoice.status==='validated')&&(page!=='issues'||invoice.status==='issue')&&(kind==='all'||invoice.kind===kind)&&(filter==='all'||invoice.status===filter)&&`${invoice.id} ${invoice.partner} ${companyName(invoice.company)}`.toLowerCase().includes(query.toLowerCase()));}
function tablePanel(compact=false){return `<section class="panel"><div class="panel-head"><div><h2>${compact?'Últimas facturas':pages[page][0]}</h2><p>${company==='all'?'Todas tus empresas':companyName(company)} · octubre 2026</p></div>${compact?'<button class="text-link" data-page="invoices">Ver todas las facturas →</button>':'<span class="badge neutral">Datos ficticios</span>'}</div><div class="tab-row">${[['all','Todas'],['received','Recibidas'],['issued','Emitidas']].map(([value,label])=>`<button class="tab ${kind===value?'active':''}" data-kind="${value}">${label}</button>`).join('')}</div><div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="Buscar facturas" placeholder="Buscar por número, empresa o contacto…" value="${escapeHtml(query)}"></label><select id="status" aria-label="Filtrar por estado"><option value="all">Todos los estados</option>${Object.entries(statusNames).map(([value,label])=>`<option value="${value}" ${filter===value?'selected':''}>${label}</option>`).join('')}</select><span class="small muted">Octubre 2026</span></div><div id="table-content">${tableContent(compact)}</div></section>`}
function tableContent(compact=page==='dashboard'){const rows=filtered();const visible=compact?rows.slice(0,5):rows;return `${visible.length?`<div class="table-wrap"><table><thead><tr><th>Factura / contacto</th><th>Empresa</th><th>Fecha</th><th class="money">Importe</th><th>Estado</th><th></th></tr></thead><tbody>${visible.map(invoice=>`<tr><td><button class="invoice-link" data-invoice="${invoice.id}"><span class="doc-icon">${icon('file')}</span><span><strong>${escapeHtml(invoice.partner)}</strong><small>${invoice.id} · ${invoice.kind==='received'?'Recibida':'Emitida'}</small></span></button></td><td>${escapeHtml(companyName(invoice.company))}</td><td>${invoice.date.split('-').reverse().join('/')}</td><td class="money">${eur(total(invoice))}</td><td>${badge(invoice)}</td><td><button class="icon-btn" data-invoice="${invoice.id}" aria-label="Abrir ${invoice.id}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>Todo despejado por aquí</h3><p>No hay facturas para esta selección. Prueba otro filtro.</p></div>'}<div class="table-footer"><span>Mostrando ${visible.length} de ${rows.length} facturas</span><span>Importes en EUR · IVA incluido</span></div>`}
function reconciliation(){const moves=db.transactions.filter(item=>company==='all'||item.company===company);return `<div class="notice">Movimientos bancarios ficticios · La coincidencia propuesta usa empresa, referencia, importe y sentido del movimiento. Confirma cada propuesta manualmente.</div><section class="panel"><div class="panel-head"><h2>Movimientos bancarios</h2><span class="badge neutral">${moves.filter(item=>!item.matched).length} por conciliar</span></div><div class="table-wrap"><table><thead><tr><th>Movimiento</th><th>Empresa</th><th>Factura propuesta</th><th class="money">Importe</th><th>Acción</th></tr></thead><tbody>${moves.map(move=>`<tr><td><strong>${escapeHtml(move.partner)}</strong><div class="small muted">${move.id} · ${move.date}</div></td><td>${companyName(move.company)}</td><td>${move.invoiceId}</td><td class="money">${eur(move.amount)}</td><td>${move.matched?'<span class="badge">✓ Conciliado</span>':`<button class="button soft" data-match="${move.id}">Confirmar coincidencia</button>`}</td></tr>`).join('')}</tbody></table></div>${!moves.length?'<div class="empty">Exporta una factura a SAP simulado para generar un movimiento de ejemplo.</div>':''}</section>`}
function bind(){document.getElementById('company').onchange=event=>{company=event.target.value;render()};const search=document.getElementById('search');if(search)search.oninput=event=>{query=event.target.value;document.getElementById('table-content').innerHTML=tableContent()};const select=document.getElementById('status');if(select)select.onchange=event=>{filter=event.target.value;render()};const fail=document.getElementById('sap-fail');if(fail)fail.onchange=event=>{db.failNext=event.target.checked;save()};}
function openModal(content,narrow=false){lastFocus=document.activeElement;document.getElementById('overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${narrow?'narrow':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1">${content}</section></div>`;document.body.style.overflow='hidden';document.querySelector('.modal').focus()}
function closeModal(){document.getElementById('overlay').innerHTML='';document.body.style.overflow='';selected=null;if(lastFocus?.isConnected)lastFocus.focus()}
function modalHead(title,subtitle){return `<div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="icon-btn" data-action="close" aria-label="Cerrar">${icon('close')}</button></div>`}
function showInvoice(id){const invoice=db.invoices.find(item=>item.id===id);if(!invoice)return;selected=id;const locked=['approved','exported','reconciled'].includes(invoice.status);openModal(`${modalHead(invoice.id,companyName(invoice.company))}<div class="modal-body"><div class="document-layout"><div class="paper"><div class="watermark">DOCUMENTO FICTICIO · SIN VALIDEZ</div><h3>Factura</h3><p>${escapeHtml(invoice.partner)}<br>${escapeHtml(invoice.nif||'Identificador pendiente')}<br>${invoice.date.split('-').reverse().join('/')}</p><div class="paper-line"><span>Servicios de ejemplo</span><span>${eur(invoice.base)}</span></div><div class="paper-line"><span>IVA ilustrativo (${invoice.vat}%)</span><span>${eur(round(invoice.base*invoice.vat/100))}</span></div><div class="paper-total">${eur(total(invoice))}</div><p>Representación generada con datos de la demo. No corresponde a un PDF real.</p>${invoice.sapRef?`<span class="badge blue">${invoice.sapRef} · Referencia ficticia</span>`:''}</div><div>${badge(invoice)}<div class="notice" style="margin-top:13px">${invoice.status==='received'?'Pendiente de extracción. El simulador rellenará campos prefijados.':`OCR / IA simulado · confianza ficticia ${invoice.confidence}%`}</div>${invoice.issue?`<div class="notice amber">${escapeHtml(invoice.issue)}</div>`:''}<form id="invoice-form"><label class="field">Contacto<input name="partner" value="${escapeHtml(invoice.partner)}" ${locked?'disabled':''} required></label><label class="field">Identificador fiscal de demostración<input name="nif" value="${escapeHtml(invoice.nif)}" placeholder="DEMO-123" ${locked?'disabled':''}></label><div class="form-grid"><label class="field">Base imponible (€)<input name="base" type="number" step="0.01" min="0.01" max="99999999" value="${invoice.base}" ${locked?'disabled':''} required></label><label class="field">IVA ilustrativo<select name="vat" ${locked?'disabled':''}>${[0,4,10,21].map(rate=>`<option ${invoice.vat===rate?'selected':''} value="${rate}">${rate}%</option>`).join('')}</select></label></div></form><div class="modal-actions">${invoice.status==='received'?'<button class="button primary" data-action="ocr">Simular OCR / IA</button>':''}${['review','issue','validated'].includes(invoice.status)?'<button class="button" data-action="save-invoice">Guardar cambios</button><button class="button primary" data-action="validate">Validar datos</button>':''}${invoice.status==='validated'?'<button class="button" data-action="return">Devolver a revisión</button><button class="button primary" data-action="approve">Aprobar factura</button>':''}${invoice.status==='approved'?'<button class="button primary" data-action="export-one">Exportar a SAP · demo</button>':''}${invoice.status==='exported'?'<button class="button primary" data-action="go-reconcile">Ir a conciliación</button>':''}</div><div class="audit"><h3>Trazabilidad local</h3>${invoice.history.map(event=>`<div class="audit-item"><strong>${escapeHtml(event.time)}</strong><br>${escapeHtml(event.text)}</div>`).join('')}</div></div></div></div>`);}
function newInvoice(){openModal(`${modalHead('Nueva factura de demostración','Crea un ejemplo para recorrer el circuito completo.')}<form id="new-form" class="modal-body"><div class="notice">Esta demo incorpora una factura prefijada. No sube archivos ni extrae datos de documentos reales.</div><label class="field">Empresa<select name="company">${companies.map(item=>`<option value="${item.id}" ${company===item.id?'selected':''}>${item.name}</option>`).join('')}</select></label><label class="field">Tipo<select name="kind"><option value="received">Factura recibida</option><option value="issued">Factura emitida</option></select></label><label class="field">Contacto ficticio<input name="partner" value="Servicios Horizonte" maxlength="100" required></label><label class="check-line"><input type="checkbox" name="error">Incluir una incidencia para demostrar su resolución</label><div class="modal-actions"><button type="button" class="button" data-action="close">Cancelar</button><button class="button primary" type="submit">Crear factura de ejemplo</button></div></form>`,true);document.getElementById('new-form').onsubmit=event=>{event.preventDefault();const data=new FormData(event.target);const invoice={id:`FAC-2026-${String(Math.max(104,...db.invoices.map(item=>Number(item.id.split('-').pop())))+1).padStart(4,'0')}`,company:data.get('company'),kind:data.get('kind'),partner:data.get('partner').trim()||'Contacto demo',nif:'',date:'2026-10-28',due:'2026-11-28',base:1250,vat:21,status:'received',confidence:96,issue:'',injectError:data.get('error')==='on',sapRef:'',history:[]};db.invoices.unshift(invoice);log(invoice,'Factura de ejemplo creada.');closeModal();render();showInvoice(invoice.id)}}
function updateFields(invoice){const form=document.getElementById('invoice-form');if(!form.reportValidity())return false;const data=new FormData(form);invoice.partner=String(data.get('partner')).trim();invoice.nif=String(data.get('nif')).trim();invoice.base=round(Number(data.get('base')));invoice.vat=Number(data.get('vat'));return true}
function validationErrors(invoice){const errors=[];if(!invoice.partner)errors.push('Indica un contacto.');if(!/^DEMO-[A-Z0-9]+$/i.test(invoice.nif))errors.push('Usa un identificador ficticio con formato DEMO-123.');if(!Number.isFinite(invoice.base)||invoice.base<=0||invoice.base>99999999)errors.push('La base debe ser positiva y menor de 100 millones.');if(![0,4,10,21].includes(invoice.vat))errors.push('Selecciona un tipo de IVA del ejemplo.');return errors}
function exportInvoice(invoice){if(invoice.status!=='approved')return false;if(db.failNext){db.failNext=false;log(invoice,'Error simulado: conector no disponible. Se conserva la aprobación para reintentar.');return false}invoice.status='exported';invoice.sapRef=`SIM-${invoice.id.replace('FAC-','')}`;db.transactions.push({id:`MOV-${db.transactions.length+1}`,company:invoice.company,partner:invoice.partner,amount:total(invoice)*(invoice.kind==='received'?-1:1),date:'2026-10-28',invoiceId:invoice.id,matched:false});log(invoice,`Exportación SAP simulada completada · ${invoice.sapRef}. Movimiento bancario ficticio generado.`);return true}
function match(id){const move=db.transactions.find(item=>item.id===id);const invoice=db.invoices.find(item=>item.id===move?.invoiceId);if(!move||move.matched||!invoice||invoice.status!=='exported'||move.company!==invoice.company||round(move.amount)!==round(total(invoice)*(invoice.kind==='received'?-1:1))){toast('No se puede confirmar esta coincidencia. Revisa el estado y el importe.');return}move.matched=true;invoice.status='reconciled';log(invoice,`Conciliación confirmada con ${move.id} · simulación.`);render();toast('Coincidencia confirmada. Circuito completado.');}
function csv(){const rows=filtered();const cell=value=>`"${String(value??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')}"`;const content=[['DEMO SIN VALIDEZ FISCAL · SAP SIMULADO'],['Factura','Empresa','Sociedad demo','Tipo','Contacto','Identificador ficticio','Fecha','Base','IVA %','Total','Estado','Referencia simulada'],...rows.map(invoice=>[invoice.id,companyName(invoice.company),companies.find(item=>item.id===invoice.company).code,invoice.kind==='received'?'Recibida':'Emitida',invoice.partner,invoice.nif,invoice.date,invoice.base.toFixed(2).replace('.',','),invoice.vat,total(invoice).toFixed(2).replace('.',','),statusNames[invoice.status],invoice.sapRef])].map(row=>row.map(cell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+content],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='nexo-facturas-DEMO.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`${rows.length} facturas descargadas. CSV ilustrativo, no importable directamente en SAP.`)}
function guide(){openModal(`${modalHead('Tu demo, en cinco minutos','Un recorrido para conversar con tus clientes.')}<div class="modal-body">${[['Elige una empresa','Usa el selector superior para ver su actividad y sus documentos.'],['Recibe y extrae','Pulsa Nueva factura, crea un ejemplo y ejecuta Simular OCR / IA. Los datos se rellenan de forma prefijada.'],['Valida y aprueba','Valida los campos y aprueba la factura. Puedes crear un ejemplo con incidencia y corregir el identificador con DEMO-123.'],['Exporta y concilia','Exporta a SAP simulado y confirma el movimiento en Conciliación. Prueba el fallo del conector desde Integración SAP.'],['Cuenta la oportunidad','Muestra las métricas y descarga el CSV. Para un proyecto real habrá que estudiar la versión de SAP, permisos, datos y requisitos fiscales.']].map(([title,body],index)=>`<div class="step"><span class="step-number">${index+1}</span><div><strong>${title}</strong><p>${body}</p></div></div>`).join('')}<div class="notice" style="margin-top:18px">Los cambios se guardan en este navegador. No hay usuarios reales, OCR real, conexión SAP ni cumplimiento fiscal certificado.</div><div class="modal-actions"><button class="button" data-action="reset-confirm">Restablecer la demo</button><button class="button primary" data-action="new">Empezar recorrido ${icon('arrow')}</button></div></div>`,true)}
document.addEventListener('click',event=>{const button=event.target.closest('button,[data-action]');if(!button)return;if(button.dataset.page)return navigate(button.dataset.page);if(button.dataset.kind){kind=button.dataset.kind;render();return}if(button.dataset.company){company=button.dataset.company;navigate('dashboard');return}if(button.dataset.invoice)return showInvoice(button.dataset.invoice);if(button.dataset.match)return match(button.dataset.match);const action=button.dataset.action;const invoice=db.invoices.find(item=>item.id===selected);if(action==='menu'){document.querySelector('.sidebar').classList.toggle('open');document.querySelector('.mobile-scrim').classList.toggle('open');return}if(action==='close')return closeModal();if(action==='guide')return guide();if(action==='new')return newInvoice();if(action==='csv')return csv();if(action==='go-reconcile'){closeModal();return navigate('reconciliation')}if(action==='reset-confirm'){openModal(`${modalHead('¿Restablecer la demostración?','Se eliminarán los cambios de este navegador.')}<div class="modal-body"><p>Volverás al escenario inicial de 24 facturas ficticias y tres empresas.</p><div class="modal-actions"><button class="button" data-action="guide">Cancelar</button><button class="button primary" data-action="reset">Restablecer</button></div></div>`,true);return}if(action==='reset'){db=seed();save();closeModal();company='all';navigate('dashboard');toast('Demo restablecida.');return}if(action==='export-all'){const ready=scope().filter(item=>item.status==='approved');let success=0;for(const item of ready){if(exportInvoice(item))success++;else break}render();toast(`${success} de ${ready.length} facturas exportadas al simulador.${success<ready.length?' Fallo simulado: puedes reintentar.':''}`);return}if(!invoice)return;
if(action==='ocr'&&invoice.status==='received'){invoice.nif=invoice.injectError?'':'DEMO-2026';invoice.status='review';log(invoice,'OCR / IA simulado ejecutado. Campos de ejemplo rellenados.');toast('Extracción simulada completada. Revisa los datos.');}
if(['save-invoice','validate'].includes(action)&&['review','issue','validated'].includes(invoice.status)){if(!updateFields(invoice))return;invoice.status='review';invoice.issue='';if(action==='validate'){const errors=validationErrors(invoice);invoice.status=errors.length?'issue':'validated';invoice.issue=errors.join(' ');log(invoice,errors.length?'Validación bloqueada: '+invoice.issue:'Validación de ejemplo superada. Pendiente de aprobación.');toast(errors.length?'Hay una incidencia que resolver.':'Datos validados. Ya puedes aprobar la factura.')}else log(invoice,'Campos modificados. Es necesario validar de nuevo.');}
if(action==='return'&&invoice.status==='validated'){invoice.status='review';log(invoice,'Devuelta a revisión por la gestora ficticia.')}
if(action==='approve'&&invoice.status==='validated'){if(!updateFields(invoice))return;const errors=validationErrors(invoice);if(errors.length){invoice.status='issue';invoice.issue=errors.join(' ');log(invoice,'Aprobación bloqueada: '+invoice.issue)}else{invoice.status='approved';log(invoice,'Factura aprobada por María López · perfil ficticio.');toast('Factura aprobada. Preparada para SAP simulado.')}}
if(action==='export-one'){const success=exportInvoice(invoice);toast(success?'Exportación simulada completada. Ya puedes conciliar.':'Fallo simulado. La factura sigue aprobada: vuelve a intentarlo.')}render();showInvoice(invoice.id);});
document.addEventListener('keydown',event=>{const modal=document.querySelector('.modal');if(!modal)return;if(event.key==='Escape')closeModal();if(event.key==='Tab'){const items=[...modal.querySelectorAll('button,input,select,[tabindex="0"]')].filter(item=>!item.disabled);const first=items[0],last=items[items.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal)){event.preventDefault();last?.focus()}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===modal)){event.preventDefault();first?.focus()}}});
render();
